def count_char_categories(s: str) -> dict:
    """Count characters of s by category.

    Return a dict with exactly the keys 'upper', 'lower', 'digit' and 'other',
    mapping to the number of uppercase letters, lowercase letters, decimal
    digits, and all remaining characters (including spaces) respectively.

    >>> count_char_categories("Ab1!")
    {'upper': 1, 'lower': 1, 'digit': 1, 'other': 1}
    >>> count_char_categories("")
    {'upper': 0, 'lower': 0, 'digit': 0, 'other': 0}
