solution:
def count_char_categories(s: str) -> dict:
    counts = {"upper": 0, "lower": 0, "digit": 0, "other": 0}
    for ch in s:
        if ch.isupper():
            counts["upper"] += 1
        elif ch.islower():
            counts["lower"] += 1
        elif ch.isdigit():
            counts["digit"] += 1
        else:
            counts["other"] += 1
    return counts

