def invert_one_to_one_mapping(d: dict) -> dict:
    """Return a new dict mapping each value of d back to its key.

    If two keys share the same value the mapping is not invertible and a
    ValueError is raised.

    >>> invert_one_to_one_mapping({'a': 1, 'b': 2})
    {1: 'a', 2: 'b'}
    >>> invert_one_to_one_mapping({})
    {}
    """

solution:
def invert_one_to_one_mapping(d: dict) -> dict:
    inverted = {}
    for key, value in d.items():
        if value in inverted:
            raise ValueError(f"duplicate value: {value!r}")
        inverted[value] = key
    return inverted

