from collections import Counter


def last_unique_character(s: str) -> str:
    counts = Counter(s)
    for ch in reversed(s):
        if counts[ch] == 1:
            return ch
    return ""

def min_gap_between_equal_values(nums: list) -> int:
    last_seen = {}
    best = -1
    for i, value in enumerate(nums):
        if value in last_seen:
            gap = i - last_seen[value]
            if best == -1 or gap < best:
                best = gap
        last_seen[value] = i
    return best

def count_pairs_with_difference(nums: list, k: int) -> int:
    seen = {}
    total = 0
    for x in nums:
        if k == 0:
            total += seen.get(x, 0)
        else:
            total += seen.get(x - k, 0) + seen.get(x + k, 0)
        seen[x] = seen.get(x, 0) + 1
    return total

def longest_span_with_k_distinct(s: str, k: int) -> int:
    counts = {}
    left = 0
    best = 0
    for right, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        while len(counts) > k:
            out = s[left]
            counts[out] -= 1
            if counts[out] == 0:
                del counts[out]
            left += 1
        best = max(best, right - left + 1)
    return best

def follows_word_pattern(pattern: str, sentence: str) -> bool:
    words = sentence.split()
    if len(words) != len(pattern):
        return False
    char_to_word = {}
    word_to_char = {}
    for ch, word in zip(pattern, words):
        if char_to_word.setdefault(ch, word) != word:
            return False
        if word_to_char.setdefault(word, ch) != ch:
            return False
    return True

def count_subarrays_summing_to(nums: list, target: int) -> int:
    prefix_counts = {0: 1}
    running = 0
    total = 0
    for x in nums:
        running += x
        total += prefix_counts.get(running - target, 0)
        prefix_counts[running] = prefix_counts.get(running, 0) + 1
    return total

