def resolve_alias_chain(aliases: dict, name: str) -> str:
    visited = set()
    current = name
    while current in aliases:
        if current in visited:
            raise ValueError(f"alias cycle at {current!r}")
        visited.add(current)
        current = aliases[current]
    return current

def sparse_vector_dot(a: dict, b: dict) -> float:
    if len(a) > len(b):
        a, b = b, a
    return sum(value * b[i] for i, value in a.items() if i in b)

from collections import Counter


def shortest_window_covering(s: str, required: str) -> str:
    if not required:
        return ""
    need = Counter(required)
    missing = len(required)
    left = 0
    best_start, best_len = 0, float("inf")
    for right, ch in enumerate(s):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1
        while missing == 0:
            if right - left + 1 < best_len:
                best_start, best_len = left, right - left + 1
            out = s[left]
            need[out] += 1
            if need[out] > 0:
                missing += 1
            left += 1
    return "" if best_len == float("inf") else s[best_start:best_start + best_len]

import heapq


def dependency_install_order(deps: dict) -> list:
    nodes = set(deps)
    for reqs in deps.values():
        nodes.update(reqs)
    indegree = {n: 0 for n in nodes}
    dependents = {n: [] for n in nodes}
    for pkg, reqs in deps.items():
        for req in set(reqs):
            dependents[req].append(pkg)
            indegree[pkg] += 1
    ready = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        n = heapq.heappop(ready)
        order.append(n)
        for m in dependents[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(ready, m)
    if len(order) != len(nodes):
        raise ValueError("dependency cycle")
    return order

from collections import Counter


def longest_substring_all_counts_at_least(s: str, k: int) -> int:
    if len(s) < k:
        return 0
    counts = Counter(s)
    for i, ch in enumerate(s):
        if counts[ch] < k:
            return max(
                longest_substring_all_counts_at_least(part, k)
                for part in s.split(ch)
            )
    return len(s)

def merge_synonym_groups(pairs: list) -> list:
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in pairs:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    groups = {}
    for word in parent:
        groups.setdefault(find(word), []).append(word)
    return sorted((sorted(g) for g in groups.values()), key=lambda g: g[0])

def count_subarrays_exactly_k_distinct(nums: list, k: int) -> int:
    def at_most(limit):
        if limit <= 0:
            return 0
        counts = {}
        left = 0
        total = 0
        for right, x in enumerate(nums):
            counts[x] = counts.get(x, 0) + 1
            while len(counts) > limit:
                y = nums[left]
                counts[y] -= 1
                if counts[y] == 0:
                    del counts[y]
                left += 1
            total += right - left + 1
        return total

    return at_most(k) - at_most(k - 1)

def longest_balanced_binary_span(bits: str) -> int:
    first_index = {0: -1}
    balance = 0
    best = 0
    for i, b in enumerate(bits):
        balance += 1 if b == "1" else -1
        if balance in first_index:
            best = max(best, i - first_index[balance])
        else:
            first_index[balance] = i
    return best

from collections import OrderedDict


def lru_cache_miss_count(capacity: int, requests: list) -> int:
    cache = OrderedDict()
    misses = 0
    for key in requests:
        if key in cache:
            cache.move_to_end(key)
            continue
        misses += 1
        if capacity == 0:
            continue
        if len(cache) >= capacity:
            cache.popitem(last=False)
        cache[key] = True
    return misses

from collections import Counter


def concatenation_start_indices(s: str, words: list) -> list:
    if not words:
        return []
    width = len(words[0])
    total = width * len(words)
    target = Counter(words)
    result = []
    for i in range(len(s) - total + 1):
        chunk = Counter(s[i + j * width:i + (j + 1) * width] for j in range(len(words)))
        if chunk == target:
            result.append(i)
    return result
